UPDATE event_invitations
SET status = #{supersededStatus}, updated_at = #{now}
WHERE space_id = #{spaceId}
  AND event_id = #{eventId}
  AND email_normalized = #{emailNormalized}
  AND status = #{pendingStatus}

UPDATE event_invitations
SET status = #{acceptedStatus}, accepted_user_id = #{acceptedUserId}, updated_at = #{now}
WHERE id = #{id} AND space_id = #{spaceId} AND event_id = #{eventId}
  AND status = #{pendingStatus} AND expires_at > #{now}

UPDATE event_invitations
SET status = #{revokedStatus}, updated_at = #{now}
WHERE id = #{id} AND space_id = #{spaceId} AND event_id = #{eventId}
  AND status = #{pendingStatus}

UPDATE event_invitations
SET status = #{revokedStatus}, updated_at = #{now}
WHERE event_id = #{eventId} AND space_id = #{spaceId} AND status = #{pendingStatus}
